}

/**
 * @internal
 */
export const QueryDocumentKeys: {
  [P in keyof ASTKindToNode]: ReadonlyArray<keyof ASTKindToNode[P]>;
} = {
  Name: [],

  Document: ['definitions'],
  OperationDefinition: [
    'name',
